const cases = [
  ["H01", "How many days of annual leave do I get?", "IN", "employee", "HR-001"],
  ["H02", "How many days of annual leave do I get?", "UK", "employee", "HR-002"],
  ["H03", "On which day is my salary paid?", "IN", "employee", "HR-005"],
  ["H04", "On which day is my salary paid?", "UK", "manager", "HR-006"],
  ["H05", "What is my notice period if I resign?", "IN", "employee", "HR-003"],
  ["H06", "What is my notice period if I resign?", "UK", "employee", "HR-004"],
  ["H07", "How many unused leave days can I carry over to next year?", "IN", "employee", "HR-001"],
  ["H08", "How do I start a performance improvement plan for someone in my team?", "UK", "manager", "HR-011"],
  ["H09", "How do I start a performance improvement plan for someone in my team?", "IN", "employee", "NONE"],
  ["H10", "What are the pay bands for my team and can I share them?", "IN", "employee", "NONE"],
  ["H11", "How many days of paid sick leave do I get?", "UK", "contractor", "HR-013"],
  ["H12", "How do I claim travel expenses?", "UK", "contractor", "HR-009"],
  ["H13", "What is the dress code in the office?", "IN", "employee", "NONE"],
  ["H14", "How many days of paid sick leave do I get?", "IN", "employee", "HR-007"]
];

const items = [];
for (const mode of ["strict", "off"]) {
  for (const c of cases) {
    items.push({ json: { case_id: c[0], question: c[1], country: c[2], role: c[3], expected: c[4], filter_mode: mode } });
  }
}
return items;

const expected = $("Load HR Cases").all().map(i => i.json);
const actual = $input.all().map(i => i.json);

const summary = { strict: { total: 0, correct: 0 }, off: { total: 0, correct: 0 } };
const rows = [];

for (let i = 0; i < expected.length; i++) {
  const e = expected[i];
  const a = actual[i] || {};
  const got = a.found ? String(a.policy_source || "").slice(0, 6) : "NONE";
  const ok = got === e.expected;
  summary[e.filter_mode].total++;
  if (ok) summary[e.filter_mode].correct++;
  rows.push({
    case_id: e.case_id, filter: e.filter_mode, who: e.country + " " + e.role, question: e.question,
    expected: e.expected, got, ok, score: a.score,
    candidates: (a.candidates || []).map(c => c.policy_id + ":" + c.score).join(", "),
    answer: a.answer
  });
}

return [{
  json: {
    with_filter: summary.strict.correct + " of " + summary.strict.total,
    without_filter: summary.off.correct + " of " + summary.off.total,
    failures: rows.filter(r => !r.ok),
    rows
  }
}];
